#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Tile {
    pub width: usize,
    pub height: usize,
    pub pixels: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Atlas {
    pub width: usize,
    pub height: usize,
    pub pixels: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AtlasError {
    EmptyInput,
    ZeroColumns,
    InvalidPixels { index: usize },
    DimensionMismatch { index: usize },
    Overflow,
}

pub fn build_atlas(tiles: &[Tile], columns: usize) -> Result<Atlas, AtlasError> {
    if columns == 0 {
        return Err(AtlasError::ZeroColumns);
    }
    let first = tiles.first().ok_or(AtlasError::EmptyInput)?;
    for (index, tile) in tiles.iter().enumerate() {
        let expected = tile.width.checked_mul(tile.height).ok_or(AtlasError::Overflow)?;
        if tile.pixels.len() != expected {
            return Err(AtlasError::InvalidPixels { index });
        }
        if tile.width != first.width || tile.height != first.height {
            return Err(AtlasError::DimensionMismatch { index });
        }
    }
    let rows = tiles.len().checked_add(columns - 1).ok_or(AtlasError::Overflow)? / columns;
    let width = first.width.checked_mul(columns).ok_or(AtlasError::Overflow)?;
    let height = first.height.checked_mul(rows).ok_or(AtlasError::Overflow)?;
    let len = width.checked_mul(height).ok_or(AtlasError::Overflow)?;
    let mut pixels = vec![0; len];
    for (index, tile) in tiles.iter().enumerate() {
        let cell_x = index % columns;
        let cell_y = index / columns;
        for y in 0..tile.height {
            let src = y * tile.width;
            let dst = (cell_y * tile.height + y) * width + cell_x * tile.width;
            pixels[dst..dst + tile.width].copy_from_slice(&tile.pixels[src..src + tile.width]);
        }
    }
    Ok(Atlas { width, height, pixels })
}
